package com.cju.likelion.cardcollection.reward.service;
import com.cju.likelion.cardcollection.auth.exception.InvalidCredentialsException; import com.cju.likelion.cardcollection.auth.repository.UserRepository; import com.cju.likelion.cardcollection.card.domain.CardStatus; import com.cju.likelion.cardcollection.card.repository.CardRepository; import com.cju.likelion.cardcollection.catalog.repository.*; import com.cju.likelion.cardcollection.reward.domain.CollectionReward; import com.cju.likelion.cardcollection.reward.dto.RewardProgressResponse; import com.cju.likelion.cardcollection.reward.repository.CollectionRewardRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class RewardProgressService {private final UserRepository users;private final CardRepository cards;private final ProductCollectionRepository collections;private final ProductCollectionItemRepository items;private final CollectionRewardRepository conditions;public RewardProgressService(UserRepository u,CardRepository c,ProductCollectionRepository pc,ProductCollectionItemRepository i,CollectionRewardRepository cr){users=u;cards=c;collections=pc;items=i;conditions=cr;} @Transactional(readOnly=true) public List<RewardProgressResponse> list(UUID userId){users.findByIdAndDeletedAtIsNull(userId).orElseThrow(InvalidCredentialsException::new);List<UUID> owned=cards.findByUserIdAndStatus(userId,CardStatus.ACTIVE).stream().map(c->c.getProduct().getId()).toList();return collections.findAll().stream().map(c->{var p=OfficialCollectionProgressCalculator.calculate(items.findByProductCollectionId(c.getId()).stream().filter(i->i.isRequired()).map(i->i.getProduct().getId()).toList(),owned);var targets=conditions.findByProductCollectionId(c.getId()).stream().map(x->target(x,p.percentage())).toList();return new RewardProgressResponse(c.getId(),c.getName(),p.requiredProductCount(),p.ownedRequiredProductCount(),p.percentage(),targets);}).toList();} private RewardProgressResponse.UnlockTarget target(CollectionReward x,java.math.BigDecimal p){boolean reward=x.getReward()!=null;return new RewardProgressResponse.UnlockTarget(reward?"REWARD":"EVENT",reward?x.getReward().getId():x.getEvent().getId(),reward?x.getReward().getName():x.getEvent().getName(),x.getRequiredPercentage(),RewardEligibilityEvaluator.isEligible(p,x.getRequiredPercentage()));}}
